package com.example.soundguardian;
import com.soundguardian.core.AppConfig;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.*;
public class MainActivity extends AppCompatActivity{
 TextView status,candidates,inputInfo,events; ProgressBar level; Button toggle; boolean listening; BroadcastReceiver rx; AppConfig config; RadarDashboard dashboard;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);try{config=new AppConfig(this);}catch(Exception e){android.util.Log.e("SoundGuardian","中文类别配置加载失败",e);}dashboard=new RadarDashboard(this);status=findViewById(R.id.status);candidates=findViewById(R.id.candidates);inputInfo=findViewById(R.id.inputInfo);events=findViewById(R.id.events);level=findViewById(R.id.level);toggle=findViewById(R.id.toggle);toggle.setOnClickListener(v->{v.animate().scaleX(.96f).scaleY(.96f).setDuration(100).withEndAction(()->{v.animate().scaleX(1).scaleY(1).setDuration(160);toggle();});});rx=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.hasExtra("error")){status.setText("异常 · "+i.getStringExtra("error"));return;}if(i.hasExtra("history"))events.setText(i.getStringExtra("history"));float[] s=i.getFloatArrayExtra("score"); String[] labels=i.getStringArrayExtra("labels"); if(s!=null&&labels!=null){Integer[] order=new Integer[s.length];for(int j=0;j<s.length;j++)order[j]=j;Arrays.sort(order,(a,b)->Float.compare(s[b],s[a]));StringBuilder z=new StringBuilder();z.append(i.getStringExtra("current")).append("\n可能候选（原生分数）\n");for(int j=0;j<Math.min(5,s.length);j++)z.append(j+1).append(" · ").append(displayName(labels[order[j]])).append("  ").append(String.format(Locale.ROOT,"%.1f%%",s[order[j]]*100)).append("\n");z.append("\n关注类别分数：");for(String label:new String[]{"Cough","Throat clearing","Knock","Tap","Slap, smack","Smash, crash","Glass","Walk, footsteps","Alarm"}){for(int k=0;k<labels.length;k++)if(labels[k].equals(label))z.append("\n").append(displayName(label)).append(" ").append(String.format(Locale.ROOT,"%.1f%%",s[k]*100));}candidates.setText(z);}if(level!=null)level.setProgress(i.getIntExtra("level",0));inputInfo.setText("16 kHz · mono · 电平仅表示输入强度");dashboard.render(i);}};registerReceiver(rx,new IntentFilter(ListenService.ACTION),Context.RECEIVER_NOT_EXPORTED);}
 String displayName(String label){return config==null?label:config.name(label);}
 void toggle(){if(!listening){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},9);return;}startForegroundService(new Intent(this,ListenService.class));listening=true;toggle.setText("停止守护");status.setText("正在启动");dashboard.listening(true);}else{stopService(new Intent(this,ListenService.class));listening=false;toggle.setText("开始守护");status.setText("尚未开始");dashboard.listening(false);if(level!=null)level.setProgress(0);}}
 protected void onDestroy(){dashboard.close();unregisterReceiver(rx);super.onDestroy();}
}


